<script lang="ts">
  import { auth } from '$lib/stores/auth'; import { goto } from '$app/navigation'; import { onMount } from 'svelte';
  let username=$state(''); let email=$state(''); let fullName=$state(''); let password=$state(''); let confirmPassword=$state(''); let error=$state(''); let success=$state(''); let loading=$state(false);
  onMount(()=>{auth.init();if($auth.isAuthenticated)goto('/dashboard')});
  async function handleSubmit(e:Event){e.preventDefault();error='';success='';if(password!==confirmPassword){error='Las contraseñas no coinciden';return}if(password.length<12){error='La contraseña debe tener al menos 12 caracteres';return}loading=true;const result=await auth.register(username,email,password,fullName);if(result.success){success='Cuenta creada. Redirigiendo al inicio de sesión…';setTimeout(()=>goto('/login'),1600)}else error=result.error||'No se pudo crear la cuenta';loading=false}
</script>
<svelte:head><title>Crear cuenta · DocuTrust</title></svelte:head>
<div class="auth-layout"><div class="auth-aside"><span class="aside-mark anim-pop">+</span><p class="eyebrow anim-rise">Empieza a proteger</p><h1 class="anim-rise d1">Una base segura<br>para cada <em>acuerdo.</em></h1><p class="anim-rise d2">Crea tu espacio documental y conserva una prueba verificable de cada cambio.</p><div class="aside-points anim-rise d3"><span>✓ Firma automática por versión</span><span>✓ Verificación pública con QR</span></div></div><section class="auth-card anim-pop"><div class="mobile-brand">DocuTrust</div><span class="eyebrow">Nuevo espacio</span><h2>Crear cuenta</h2><p class="intro">Completa tus datos para configurar tus claves de firma.</p>{#if error}<div class="alert error anim-shake" role="alert">⚠ {error}</div>{/if}{#if success}<div class="alert success anim-slide" role="status">✓ {success}</div>{/if}<form onsubmit={handleSubmit}><label for="fullName">Nombre completo<input id="fullName" type="text" bind:value={fullName} placeholder="Ej. Ana García" required disabled={loading} autocomplete="name"></label><label for="username">Nombre de usuario<input id="username" type="text" bind:value={username} placeholder="ana.garcia" required disabled={loading} autocomplete="username"></label><label for="email">Correo electrónico<input id="email" type="email" bind:value={email} placeholder="tu@correo.com" required disabled={loading} autocomplete="email"></label><div class="row"><label for="password">Contraseña<input id="password" type="password" bind:value={password} placeholder="Mínimo 12 caracteres" required disabled={loading} autocomplete="new-password"></label><label for="confirmPassword">Confirmar<input id="confirmPassword" type="password" bind:value={confirmPassword} placeholder="Repite la contraseña" required disabled={loading} autocomplete="new-password"></label></div><p class="hint">Usa mayúsculas, minúsculas, números y un carácter especial.</p><button class="submit btn-anim" class:is-loading={loading} type="submit" disabled={loading}>{loading?'Creando cuenta…':'Crear cuenta'} <span>→</span></button></form><p class="switch">¿Ya tienes una cuenta? <a href="/login">Iniciar sesión</a></p></section></div>
