 solid #fecdd3;color:#be123c}.alert.success{background:#ecfdf5;border:1px solid #bbf7d0;color:#047857}@media(max-width:760px){.auth-layout{grid-template-columns:1fr;max-width:470px}.auth-aside{display:none}.mobile-brand{display:block;color:#4f46e5;font-weight:900;margin-bottom:25px}}@media(max-width:500px){.auth-layout{padding:12px 0}.auth-card{padding:24px 19px}.row{display:grid;gap:0}}
